import { useQuery } from '@tanstack/react-query';
import { clientContactsKey, fetchClientContacts, type Contact } from './queries';

// The contacts kept for one client. Queries for itself under ['clients', clientId, 'contacts'] —
// never handed its data by a parent (CLAUDE.md rule 5). Carries the stable data-testid contract:
// the table, a row per contact, and the name/email/role cells the test reads.
export function ClientContactsTable({ clientId }: { clientId: number }) {
  const { data: contacts } = useQuery({
    queryKey: clientContactsKey(clientId),
    queryFn: () => fetchClientContacts(clientId),
  });

  if (!contacts) {
    return null;
  }

  return (
    <table data-testid="client-contacts-table">
      <thead>
        <tr>
          <th>Name</th>
          <th>Email</th>
          <th>Role</th>
        </tr>
      </thead>
      <tbody>
        {contacts.map((contact: Contact) => (
          <tr key={contact.id} data-testid={`contact-row-${contact.id}`}>
            <td data-testid="contact-name">{contact.name}</td>
            <td data-testid="contact-email">{contact.email}</td>
            <td data-testid="contact-role">{contact.role}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}
===== features/contacts/queries.ts =====
import { getJson, postJson } from '../../api/http';

// A client's contacts under a key nested beneath ['clients'] so invalidating clients refreshes them
// too (CLAUDE.md rule 5). Each contact carries a name, an email and a role.
export type Contact = { id: number; name: string; email: string; role: string };

export const clientContactsKey = (clientId: number) =>
  ['clients', clientId, 'contacts'] as const;

// A "proper email address": one @, non-empty local and domain parts, and a dotted domain. Shared by
// the form and mirrored by the server so a malformed address can never be saved.
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function isValidEmail(email: string): boolean {
  return EMAIL_PATTERN.test(email.trim());
}

export function fetchClientContacts(clientId: number): Promise<Contact[]> {
  return getJson<Contact[]>(`/api/clients/${clientId}/contacts`);
}

export function createContact(input: {
  name: string;
  email: string;
  role: string;
  clientId: number;
}): Promise<Contact> {
  return postJson<Contact>('/api/contacts', input);
}

