===== features/invoices/pay.slot.tsx =====
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { InvoiceRow } from '../../slots/defs/invoiceRow';
import { invoicesKey, payInvoice } from './queries';

// The "mark this invoice paid" action on every invoice row — its own file filling the invoice.row
// region (CLAUDE.md rule 3). Payment is only allowed once the invoice has been SENT, so the button
// renders only while the row's status (from context) is SENT; a DRAFT row shows nothing here. The
// write is a mutation that invalidates ['invoices', projectId] so the list (and its status cell)
// refresh themselves (rule 5); the audited record is written server-side. Carries
// data-testid="invoice-pay-<id>" (the test contract).
export const contribution = InvoiceRow.fill({
  order: 20,
  Component: ({ invoiceId, projectId, status }: { invoiceId: number; projectId: number; status: string }) => {
    const queryClient = useQueryClient();
    const mutation = useMutation({
      mutationFn: () => payInvoice(invoiceId),
      onSuccess: () => {
        void queryClient.invalidateQueries({ queryKey: invoicesKey(projectId) });
      },
    });
    if (status !== 'SENT') {
      return null;
    }
    return (
      <td>
        <button
          data-testid={`invoice-pay-${invoiceId}`}
          type="button"
          onClick={() => mutation.mutate()}
        >
          Mark paid
        </button>
      </td>
    );
  },
});
===== features/invoices/queries.ts =====
import { getJson, postJson } from '../../api/http';

// A project's invoices under a per-project key: anything showing project 1's invoices reads
// ['invoices', 1], and a write invalidates the same key to refresh them (CLAUDE.md rule 5). An
// invoice carries its own id, its project's id and a monetary amount.
export type Invoice = {
  id: number;
  projectId: number;
  amount: number;
  status: string;
  issuedDate: string;
  dueDate: string;
};

export const invoicesKey = (projectId: number) => ['invoices', projectId] as const;

// Every invoice across all projects, each carrying the NAME of its project (the cross-entity join
// is done server-side, in AllInvoicesGet). Read under ['invoices', 'all'] (CLAUDE.md rule 5).
export type AllInvoice = {
  id: number;
  projectId: number;
  projectName: string;
  amount: number;
  status: string;
};

export const allInvoicesKey = ['invoices', 'all'] as const;

export function fetchAllInvoices(): Promise<AllInvoice[]> {
  return getJson<AllInvoice[]>('/api/invoices');
}

/** URL key owned by the sort control; readers (the list) sort by the same key (CLAUDE.md rule 4). */
export const INVOICE_SORT_PARAM = 'invoiceSort';

/** URL key owned by the stage filter; the all-invoices list narrows to this stage (CLAUDE.md rule 4). */
export const INVOICE_STATUS_PARAM = 'invoiceStatus';

/** The lifecycle stages an invoice can sit at — the options the stage filter offers. */
export const INVOICE_STATUSES = ['DRAFT', 'SENT', 'PAID'] as const;

export function fetchInvoices(projectId: number): Promise<Invoice[]> {
  return getJson<Invoice[]>(`/api/invoices/${projectId}`);
}

export function createInvoice(input: { projectId: number; amount: number }): Promise<Invoice> {
  return postJson<Invoice>('/api/invoices', input);
}

/** Send a draft invoice; the server moves it to SENT and records the audited side-effect. */
export function sendInvoice(invoiceId: number): Promise<Invoice> {
  return postJson<Invoice>(`/api/invoices/${invoiceId}/send`, {});
}

/** Mark an invoice paid; the server flips its status and records the audited side-effect. */
export function payInvoice(invoiceId: number): Promise<Invoice> {
  return postJson<Invoice>(`/api/invoices/${invoiceId}/pay`, {});
}
===== features/invoices/InvoicesTable.tsx =====
import { useQuery } from '@tanstack/react-query';
import { invoicesKey, fetchInvoices, INVOICE_SORT_PARAM, type Invoice } from './queries';
import { InvoiceRow } from '../../slots/defs/invoiceRow';
import { InvoicesToolbar } from '../../slots/defs/invoicesToolbar';
import { useSearchParam, asString } from '../../url/useSearchParam';
import { formatMoney } from '../../ui/money';

// A project's invoices list plus the derived total. Queries for itself under ['invoices', projectId]
// — never handed its data by a parent (CLAUDE.md rule 5). Amounts render with 2 decimals; the total
// is a client-side aggregate of the same rows, so it stays in step with them for free.
export function InvoicesTable({ projectId }: { projectId: number }) {
  const { data: invoices } = useQuery({
    queryKey: invoicesKey(projectId),
    queryFn: () => fetchInvoices(projectId),
  });
  // Which sort is active lives in the URL (CLAUDE.md rule 4); the sort control owns the key and this
  // list reads it. Due dates are stored as ISO strings, so a plain string compare is chronological.
  const [sort] = useSearchParam(INVOICE_SORT_PARAM, asString);

  if (!invoices) {
    return null;
  }

  const rows =
    sort === 'due'
      ? [...invoices].sort((a, b) => (a.dueDate ?? '').localeCompare(b.dueDate ?? ''))
      : invoices;

  const total = invoices.reduce((sum, invoice) => sum + Number(invoice.amount), 0);

  return (
    <>
      <InvoicesToolbar.Slot projectId={projectId} />
      <table data-testid="project-invoices-table">
        <thead>
          <tr>
            <th>Amount</th>
            <th />
          </tr>
        </thead>
        <tbody>
          {rows.map((invoice: Invoice) => (
            <tr key={invoice.id} data-testid={`invoice-row-${invoice.id}`}>
              <td data-testid="invoice-amount">{formatMoney(invoice.amount)}</td>
              <InvoiceRow.Slot
                invoiceId={invoice.id}
                projectId={projectId}
                status={invoice.status}
              />
            </tr>
          ))}
        </tbody>
      </table>
      <p data-testid="project-invoices-total">{formatMoney(total)}</p>
    </>
  );
}

